      "subtitle": "Waterfalls, Root Bridges & Safari",
      "tagline": "Waterfalls, Root Bridges & Safari",
      "categoryBadge": "Group Trip",
      "category": "group",
      "type": "group",
      "duration": "7 Days 6 Nights",
      "price": 24800,
